from rules import select


def solve(data):
    versions = select(data)
    if versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': versions}

def select(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def is_acyclic(selected_rows):
        edges = {}
        for name, row in selected_rows.items():
            active = []
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                active.append(dep['name'])
            edges[name] = active

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in edges.get(name, []):
                if dependency not in selected_rows or not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected_rows)

    def search(versions, constraints, selected_rows):
        nonlocal best_vector, best_versions

        for name, version in versions.items():
            bounds = constraints.get(name)
            if bounds is not None and not (bounds[0] <= version <= bounds[1]):
                return
            if name in pins and version != pins[name]:
                return

        pending = sorted(set(constraints) - set(versions))
        if not pending:
            if not is_acyclic(selected_rows):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        name = pending[0]
        bounds = constraints[name]
        forbidden = blocked.get(name, ())
        for row in packages.get(name, []):
            version = row['version']
            if version in forbidden or not (bounds[0] <= version <= bounds[1]):
                continue
            if name in pins and version != pins[name]:
                continue

            next_versions = dict(versions)
            next_versions[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = dict(constraints)
            feasible = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                dep_bounds = (dep['min'], dep['max'])
                old_bounds = next_constraints.get(dep_name)
                if old_bounds is not None:
                    dep_bounds = (max(old_bounds[0], dep_bounds[0]),
                                  min(old_bounds[1], dep_bounds[1]))
                if dep_bounds[0] > dep_bounds[1]:
                    feasible = False
                    break
                next_constraints[dep_name] = dep_bounds
                if dep_name in next_versions and not (
                    dep_bounds[0] <= next_versions[dep_name] <= dep_bounds[1]
                ):
                    feasible = False
                    break

            if feasible:
                search(next_versions, next_constraints, next_rows)

    constraints = {name: tuple(bounds) for name, bounds in roots.items()}
    search({}, constraints, {})
    return best_versions
